-- CASA MINGO S.A. / Deposito principal: apertura segun inventario de enero de 2026.
-- PROTECCION: NO INVENTAR 10 PARA TODOS LOS PRODUCTOS.
-- 465 cantidades POSITIVAS del Excel, 89 cantidades explicitas CERO,
-- 7 vacias que el responsable pidio completar con 10.
-- Total esperado: 91.864 unidades sobre 472 SKUs con stock; 89 con 0.
-- Precio de venta: se respeta exactamente el Excel ya importado, sin UPDATE.
-- El Excel NO contiene COSTO DE ADQUISICION: se exige criterio de valorizacion.
-- PRECIO_EXCEL usa el precio de VENTA como costo provisional (solo si autorizado).
-- COSTO_FIJO usa un costo unitario PYG expresamente autorizado (incluido 0).
-- NO EJECUTAR antes de backup, auditoria y aprobacion del costo.
-- Motor oficial NEX-014, 2 movimientos (300+172 lineas), usuario con permisos.
-- Los 2 productos PRD-000001/2 no se tocan. No escribe saldos directamente.
\set ON_ERROR_STOP on
\if :{?autorizar_apertura}
\else
  \echo 'ABORTADO: requiere -v autorizar_apertura=true'
  \quit 2
\endif
\if :autorizar_apertura
\else
  \echo 'ABORTADO: autorizacion debe ser true'
  \quit 2
\endif
\if :{?usuario_uuid}
\else
  \echo 'ABORTADO: requiere -v usuario_uuid=UUID_REAL_CON_MOVIMIENTOS_CREAR'
  \quit 2
\endif
\if :{?criterio_costo}
\else
  \echo 'ABORTADO: requiere -v criterio_costo=PRECIO_EXCEL o COSTO_FIJO'
  \quit 2
\endif

BEGIN;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='180s';
SELECT set_config('casa_mingo.usuario_uuid', :'usuario_uuid', true);
SELECT set_config('casa_mingo.criterio_costo', :'criterio_costo', true);
\if :{?costo_unitario}
 SELECT set_config('casa_mingo.costo_fijo', :'costo_unitario', true);
\else
 SELECT set_config('casa_mingo.costo_fijo', '', true);
\endif
SELECT pg_advisory_xact_lock(hashtextextended('CASA-MINGO-APERTURA-EXCEL-20261020', 0));

