CREATE TEMP TABLE cm_movimientos_apertura (
  lote int PRIMARY KEY,
  movimiento_id uuid NOT NULL,
  numero_movimiento text NOT NULL,
  repetido boolean NOT NULL,
  cantidad_productos int NOT NULL,
  cantidad_unidades numeric(18,4) NOT NULL
) ON COMMIT DROP;

DO $preflight$
DECLARE
 e uuid := '12463e0f-55f7-4a0c-aad1-dc0681ca68b7';
 d uuid := 'a207eebb-aca7-42d3-bdab-373f4f08523b';
 u uuid := current_setting('casa_mingo.usuario_uuid')::uuid;
 modo text := current_setting('casa_mingo.criterio_costo');
 fijo text := current_setting('casa_mingo.costo_fijo',true);
 cnt int;
BEGIN
 IF modo NOT IN ('PRECIO_EXCEL','COSTO_FIJO') THEN
   RAISE EXCEPTION 'criterio_costo invalido: seleccionar PRECIO_EXCEL o COSTO_FIJO explicitamente';
 END IF;
 IF modo='COSTO_FIJO' THEN
   IF COALESCE(fijo,'') !~ '^([0-9]+)(\\.[0-9]{1,4})?$' THEN
     RAISE EXCEPTION 'costo_unitario debe ser numero PYG no negativo con hasta 4 decimales';
   END IF;
   IF fijo::numeric > 99999999999999 THEN RAISE EXCEPTION 'costo_unitario excesivo'; END IF;
 END IF;
 IF NOT EXISTS (SELECT 1 FROM empresas WHERE id=e AND codigo='80003314'
       AND razon_social='CASA MINGO S.A.' AND estado='ACTIVA' AND NOT es_demo AND moneda_base_codigo='PYG') THEN
   RAISE EXCEPTION 'Empresa UUID / codigo 80003314 no coincide con CASA MINGO S.A.';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM depositos WHERE id=d AND empresa_id=e
                AND codigo='DEP-PRINCIPAL' AND activo) THEN
   RAISE EXCEPTION 'Deposito principal no coincide o inactivo';
 END IF;
 IF NOT usuario_tiene_permiso(e,u,'MOVIMIENTOS','CREAR') OR NOT usuario_puede_deposito(e,u,d) THEN
   RAISE EXCEPTION 'Usuario sin MOVIMIENTOS.CREAR o sin alcance al deposito principal';
 END IF;
 SELECT count(*) INTO cnt FROM cm_stock_origen;
 IF cnt<>561 THEN RAISE EXCEPTION 'Esperados 561 productos en la fuente, recibidos %',cnt; END IF;
 IF (SELECT count(*) FROM cm_stock_origen WHERE cantidad_objetivo>0 AND regla_cantidad='EXCEL')<>465 OR
    (SELECT count(*) FROM cm_stock_origen WHERE cantidad_objetivo=0 AND regla_cantidad='EXCEL')<>89 OR
    (SELECT count(*) FROM cm_stock_origen WHERE cantidad_objetivo=10 AND regla_cantidad='FALTANTE_COMPLETADO_10')<>7 OR
    (SELECT sum(cantidad_objetivo) FROM cm_stock_origen)<>91864 THEN
    RAISE EXCEPTION 'Fuente/normalizacion no coincide con 465 positivos, 89 ceros, 7 faltantes y 91864 unidades';
 END IF;
 IF (SELECT count(*) FROM cm_stock_origen src JOIN productos p ON p.empresa_id=e AND p.codigo=src.codigo)<>561 THEN
   RAISE EXCEPTION 'No corresponden los 561 codigos a productos de CASA MINGO';
 END IF;
 IF EXISTS (
   SELECT 1 FROM cm_stock_origen src JOIN productos p ON p.empresa_id=e AND p.codigo=src.codigo
   WHERE NOT p.activo OR NOT p.controla_stock OR p.modo_control_stock<>'CANTIDAD'
 ) THEN RAISE EXCEPTION 'Producto inactivo, sin stock o control distinto de CANTIDAD'; END IF;
 IF EXISTS (
  SELECT 1 FROM cm_stock_origen src JOIN productos p ON p.empresa_id=e AND p.codigo=src.codigo
  LEFT JOIN v_producto_precio_referencia pr ON pr.empresa_id=e AND pr.producto_id=p.id
  WHERE pr.precio IS DISTINCT FROM src.precio_venta_excel OR pr.moneda IS DISTINCT FROM 'PYG'
 ) THEN RAISE EXCEPTION 'Precio de referencia difiere de Excel o no es PYG; revisar sin sobrescribir precios'; END IF;
 IF EXISTS (
   SELECT 1 FROM cm_stock_origen src JOIN productos p ON p.empresa_id=e AND p.codigo=src.codigo
   JOIN stock_saldos s ON s.empresa_id=e AND s.producto_id=p.id WHERE s.cantidad<>0
 ) THEN RAISE EXCEPTION 'Existen saldos previos en uno o mas depositos/estados: no sumar cantidades'; END IF;
 IF EXISTS (
   SELECT 1 FROM cm_stock_origen src JOIN productos p ON p.empresa_id=e AND p.codigo=src.codigo
   JOIN inventario_costos ic ON ic.empresa_id=e AND ic.producto_id=p.id
   WHERE ic.cantidad_valorizada<>0 OR ic.valor_total<>0
 ) THEN RAISE EXCEPTION 'Existen costos/inventario valorizado anteriores: no duplicar'; END IF;
 IF EXISTS (SELECT 1 FROM movimientos_inventario m
   WHERE m.empresa_id=e AND m.clave_idempotencia IN
     ('CM-EXCEL-20261020-LOTE1','CM-EXCEL-20261020-LOTE2')) THEN
   RAISE EXCEPTION 'Apertura EXCEL ya registrada; prohibida la duplicacion'; END IF;
END $preflight$;

DO $registro$
DECLARE
 e uuid := '12463e0f-55f7-4a0c-aad1-dc0681ca68b7';
 d uuid := 'a207eebb-aca7-42d3-bdab-373f4f08523b';
 u uuid := current_setting('casa_mingo.usuario_uuid')::uuid;
 modo text := current_setting('casa_mingo.criterio_costo');
 fijo numeric := NULLIF(current_setting('casa_mingo.costo_fijo',true),'')::numeric;
 r record;
 mov_id uuid;
 num text;
 repetido boolean;
BEGIN
 FOR r IN
  WITH seleccion AS (
   SELECT p.id, src.codigo, src.cantidad_objetivo,src.precio_venta_excel,
          row_number() OVER (ORDER BY src.codigo) AS orden
   FROM cm_stock_origen src JOIN productos p ON p.empresa_id=e AND p.codigo=src.codigo
   WHERE src.cantidad_objetivo>0
  ), lotes AS (
   SELECT CASE WHEN orden<=300 THEN 1 ELSE 2 END AS lote,id,codigo,cantidad_objetivo,
          CASE WHEN modo='PRECIO_EXCEL' THEN precio_venta_excel ELSE fijo END AS costo_unitario
   FROM seleccion
  )
  SELECT lote, count(*)::int AS productos, SUM(cantidad_objetivo) AS unidades,
     jsonb_agg(jsonb_build_object(
       'producto_id',id,'cantidad',cantidad_objetivo,'costo_unitario',costo_unitario,
       'propiedad','PROPIO') ORDER BY codigo) AS lineas
  FROM lotes GROUP BY lote ORDER BY lote
 LOOP
  SELECT o_movimiento_id,o_numero,o_repetido INTO STRICT mov_id,num,repetido
    FROM inventario_registrar_movimiento(
      e,u,'ENTRADA','ABERTURA',(now() AT TIME ZONE 'America/Asuncion')::date,
      NULL::uuid,d,r.lineas,'CM-EXCEL-20261020-LOTE'||r.lote,
      NULL::uuid,'Apertura inicial desde planilla enero 2026 con cantidad original y defaults autorizados',
      'Stock de referencia operativo; costo segun criterio autorizado: '||modo,
      'CASA-MINGO-INVENTARIO-ENERO-2026');
  IF repetido THEN RAISE EXCEPTION 'Movimiento repetido en lote %; abortado',r.lote; END IF;
  INSERT INTO cm_movimientos_apertura VALUES(r.lote,mov_id,num,repetido,r.productos,r.unidades);
 END LOOP;
END $registro$;

DO $auditoria$
DECLARE
 e uuid := '12463e0f-55f7-4a0c-aad1-dc0681ca68b7';
 d uuid := 'a207eebb-aca7-42d3-bdab-373f4f08523b';
 n int;
BEGIN
 IF (SELECT count(*) FROM cm_movimientos_apertura)<>2
    OR (SELECT sum(cantidad_productos) FROM cm_movimientos_apertura)<>472
    OR (SELECT sum(cantidad_unidades) FROM cm_movimientos_apertura)<>91864 THEN
   RAISE EXCEPTION 'El motor no registro dos movimientos, 472 productos positivos y 91864 unidades';
 END IF;
 SELECT count(*) INTO n FROM cm_stock_origen src JOIN productos p
   ON p.empresa_id=e AND p.codigo=src.codigo
 WHERE COALESCE((
   SELECT sum(s.cantidad) FROM stock_saldos s
   WHERE s.empresa_id=e AND s.producto_id=p.id AND s.deposito_id=d
     AND s.propiedad='PROPIO' AND s.estado_stock='DISPONIBLE'),0)=src.cantidad_objetivo;
 IF n<>561 THEN RAISE EXCEPTION 'Auditoria de stock no coincide: % de 561',n; END IF;
 SELECT count(*) INTO n FROM cm_stock_origen src JOIN productos p
  ON p.empresa_id=e AND p.codigo=src.codigo
  LEFT JOIN inventario_costos ic ON ic.empresa_id=e AND ic.producto_id=p.id AND ic.deposito_id=d
 WHERE COALESCE(ic.cantidad_valorizada,0)=src.cantidad_objetivo;
 IF n<>561 THEN RAISE EXCEPTION 'Auditoria de valorizacion no coincide: % de 561',n; END IF;
END $auditoria$;

\echo '=== Movimientos de apertura ==='
TABLE cm_movimientos_apertura;
\echo '=== Totales del inventario (incluye 89 con 0) ==='
SELECT count(*) AS productos, count(*) FILTER (WHERE cantidad_objetivo>0) AS productos_con_stock,
 count(*) FILTER (WHERE cantidad_objetivo=0) AS productos_sin_stock,
 sum(cantidad_objetivo) AS unidades,
 count(*) FILTER (WHERE regla_cantidad='FALTANTE_COMPLETADO_10') AS cantidades_faltantes_completadas
FROM cm_stock_origen;
COMMIT;
-- APERTURA REAL: revisar UI Stock/Movimientos, no confundir con conteo fisico certificado.
